-- Phase 4.1: additive correlation data architecture. Existing data is preserved.
CREATE TABLE IF NOT EXISTS indicator_observations (id INTEGER PRIMARY KEY, indicator_id INTEGER NOT NULL, source_analysis_type VARCHAR(40) NOT NULL, source_analysis_id VARCHAR(160) NOT NULL, normalized_value VARCHAR(2048) NOT NULL, original_observed_value TEXT NOT NULL, source_provider VARCHAR(120), verification_status VARCHAR(30) DEFAULT 'unknown', confidence FLOAT, metadata_json TEXT DEFAULT '{}', first_observed TIMESTAMP, last_observed TIMESTAMP, observation_count INTEGER DEFAULT 1, FOREIGN KEY(indicator_id) REFERENCES threat_indicators(id), CONSTRAINT uq_indicator_observation_source UNIQUE(indicator_id, source_analysis_type, source_analysis_id, normalized_value));
CREATE INDEX IF NOT EXISTS ix_indicator_observations_indicator_id ON indicator_observations(indicator_id);
CREATE INDEX IF NOT EXISTS ix_indicator_observations_source_analysis_id ON indicator_observations(source_analysis_id);
CREATE INDEX IF NOT EXISTS ix_indicator_observations_normalized_value ON indicator_observations(normalized_value);
CREATE TABLE IF NOT EXISTS indicator_relationships (id INTEGER PRIMARY KEY, source_indicator_id INTEGER NOT NULL, target_indicator_id INTEGER NOT NULL, relationship_type VARCHAR(80) NOT NULL, status VARCHAR(30) DEFAULT 'observed', confidence FLOAT, first_observed TIMESTAMP, last_observed TIMESTAMP, originating_analysis_type VARCHAR(40), originating_analysis_id VARCHAR(160), FOREIGN KEY(source_indicator_id) REFERENCES threat_indicators(id), FOREIGN KEY(target_indicator_id) REFERENCES threat_indicators(id), CONSTRAINT uq_indicator_relationship UNIQUE(source_indicator_id, target_indicator_id, relationship_type));
CREATE INDEX IF NOT EXISTS ix_indicator_relationships_source_indicator_id ON indicator_relationships(source_indicator_id);
CREATE INDEX IF NOT EXISTS ix_indicator_relationships_target_indicator_id ON indicator_relationships(target_indicator_id);
CREATE INDEX IF NOT EXISTS ix_indicator_relationships_originating_analysis_id ON indicator_relationships(originating_analysis_id);
CREATE TABLE IF NOT EXISTS correlation_results (id INTEGER PRIMARY KEY, source_analysis_type VARCHAR(40), source_analysis_id VARCHAR(160), relationship_type VARCHAR(80) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'observed', confidence FLOAT, explanation TEXT, result_json TEXT DEFAULT '{}', first_observed TIMESTAMP, last_observed TIMESTAMP);
CREATE INDEX IF NOT EXISTS ix_correlation_results_source_analysis_type ON correlation_results(source_analysis_type);
CREATE INDEX IF NOT EXISTS ix_correlation_results_source_analysis_id ON correlation_results(source_analysis_id);
CREATE TABLE IF NOT EXISTS correlation_evidence (id INTEGER PRIMARY KEY, relationship_id INTEGER, result_id INTEGER, evidence_type VARCHAR(80) NOT NULL, source VARCHAR(120) NOT NULL, details_json TEXT DEFAULT '{}', confidence FLOAT, observed_at TIMESTAMP, FOREIGN KEY(relationship_id) REFERENCES indicator_relationships(id), FOREIGN KEY(result_id) REFERENCES correlation_results(id));
CREATE INDEX IF NOT EXISTS ix_correlation_evidence_relationship_id ON correlation_evidence(relationship_id);
CREATE INDEX IF NOT EXISTS ix_correlation_evidence_result_id ON correlation_evidence(result_id);
CREATE TABLE IF NOT EXISTS correlation_analysis_events (id INTEGER PRIMARY KEY, analysis_type VARCHAR(40) NOT NULL, analysis_id VARCHAR(160) NOT NULL, event_type VARCHAR(60) NOT NULL, actor VARCHAR(160) NOT NULL DEFAULT 'system', details_json TEXT DEFAULT '{}', created_at TIMESTAMP);
CREATE INDEX IF NOT EXISTS ix_correlation_analysis_events_analysis_id ON correlation_analysis_events(analysis_id);
